// src/components/Metrices/AutomationMetricMain/TestCaseCountTab.js

// CHANGE: add useEffect/useOutletContext for Application list; keep prior imports
import React, { useEffect, useMemo, useState } from "react";
import { useOutletContext } from "react-router-dom"; // CHANGE: for projectDetails.application CSV
import "../../../styles/roiTabs.css"; // keep using your existing ROI tab styles

const API_BASE = ""; // same-origin
const GET = async (url) => (await fetch(url)).json();
const POST = async (url, body) =>
  (await fetch(url, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) })).json();



// CHANGE: automation sub-buttons (mirrors your ProjectSavingsTab)
const AUTO_SUB_TABS = [
  "Conformiq-Robot",
  "Standalone Robot",
  "Standalone Selenium (With Python/Java/C# etc)",
  "Robot (With Selenium / Playwright Library)",
  "SOA API",
  "UFT Scriptless",
  "UFT Scripted",
  "Java Only",
  "Python Only",
  "Other Utilities",
];

// CHANGE: three logical sections; Execution will be expanded into 5 phases in UI
const AUTO_SECTIONS = [
  "New Automation",
  "Existing TCs Updated",
  "Execution (SIT + UAT)",
];

const EXEC_PHASES = ["DIT", "SIT", "UAT", "Rollback", "Roll Forward"];

// tiny helper
const num = (v) => (Number.isFinite(+v) ? +v : 0);

const mkCounts = () => ({ func: 0, regression: 0, total: 0 });
const mkExecBundle = () =>
  EXEC_PHASES.reduce((acc, ph) => ((acc[ph] = { total: 0 }), acc), {});
const mkAutoBundle = () =>
  Object.fromEntries(
    AUTO_SECTIONS.map((s) =>
      s === "Execution (SIT + UAT)" ? [s, mkExecBundle()] : [s, mkCounts()]
    )
  );

export default function TestCaseCountTab() {
  const [activeTab, setActiveTab] = useState("Manual"); // "Manual" | "Automation"
  const [activeAuto, setActiveAuto] = useState(AUTO_SUB_TABS[0]);

  // TDM (Manual) section
  const [manualDesigned, setManualDesigned] = useState(mkCounts()); // New + Updated combined input
  const [manualExecuted, setManualExecuted] = useState(mkCounts());

  // Automation section
  const [autoBySub, setAutoBySub] = useState(
    Object.fromEntries(AUTO_SUB_TABS.map((k) => [k, mkAutoBundle()]))
  );

  // update helpers for normal sections and exec phases
  const updateAuto = (subKey, section, field, value) => {
    if (section === "Execution (SIT + UAT)") return; // use updateExec for phases
    setAutoBySub((prev) => ({
      ...prev,
      [subKey]: {
        ...prev[subKey],
        [section]: {
          ...prev[subKey][section],
          [field]: value,
        },
      },
    }));
  };

  const updateExec = (subKey, phase, value) => {
    setAutoBySub((prev) => ({
      ...prev,
      [subKey]: {
        ...prev[subKey],
        ["Execution (SIT + UAT)"]: {
          ...prev[subKey]["Execution (SIT + UAT)"],
          [phase]: {
            ...prev[subKey]["Execution (SIT + UAT)"][phase],
            total: value,
          },
        },
      },
    }));
  };

  // recompute section totals from func/regression inputs
  useEffect(() => {
    setManualDesigned((prev) => ({ ...prev, total: num(prev.func) + num(prev.regression) }));
  }, [manualDesigned.func, manualDesigned.regression]);

  useEffect(() => {
    setManualExecuted((prev) => ({ ...prev, total: num(prev.func) + num(prev.regression) }));
  }, [manualExecuted.func, manualExecuted.regression]);

  const sectionSum = (obj) => num(obj.func) + num(obj.regression);

  const sectionMismatch = (obj) => sectionSum(obj) !== num(obj.total);

  // =========================
  //  Application dropdown (same logic as ProjectSavingsTab)
  // =========================
  
  
  const ctx = useOutletContext() || {};
  const projectDetails = ctx.projectDetails;
  const projectLabel = ctx.projectLabel || "";
  const portfolio     = ctx.portfolio || "";
  const applicationOptions = ctx.appOptions || [];
  const defaultApp    = ctx.defaultApp || "";

  //  global Application selection for Automation band
  const [selectedApplication, setSelectedApplication] = useState("");

    useEffect(() => {
    if (!selectedApplication && (defaultApp || applicationOptions.length > 0)) {
      setSelectedApplication(defaultApp || applicationOptions[0]);
    }
  }, [defaultApp, applicationOptions, selectedApplication]);

  const [apiAppOptions, setApiAppOptions] = useState([]);

  // FIX: fetch application options if CSV is empty, using current portfolio/domain
  useEffect(() => {
    const needsFetch = applicationOptions.length === 0;
    const dom = projectDetails?.domain || projectDetails?.Portfolio || "";
    if (!needsFetch || !dom) return;
   (async () => {
      try {
        const res = await fetch(`${API_BASE}/api/fetchapplication?domain=${encodeURIComponent(dom)}`);
        const data = await res.json();
        const list = Array.from(new Set((Array.isArray(data) ? data : []).map(String).map(s => s.trim()).filter(Boolean)));
        setApiAppOptions(list);
        // pick a default immediately if none selected yet
        if (!selectedApplication && list.length > 0) setSelectedApplication(list[0]);
      } catch (e) {
       console.error("Failed to fetch application options", e);
      }
    })();
  }, [applicationOptions.length, projectDetails?.domain, projectDetails?.Portfolio, selectedApplication]);

  useEffect(() => {
  if (selectedApplication) return;
  const eff = apiAppOptions.length > 0 ? apiAppOptions : applicationOptions;
  if (eff.length > 0) setSelectedApplication(eff[0]);
}, [applicationOptions, apiAppOptions, selectedApplication]);

  
  //const intakeNumber = projectDetails?.intake_number || "";
  //const intakeName = projectDetails?.intake_name || "";
  //const projectLabel = [intakeNumber, intakeName].filter(Boolean).join("-");
  //const portfolio = projectDetails?.domain || projectDetails?.Portfolio || "";

 useEffect(() => {
   if (activeTab !== "Automation") return;
   loadAutomationTotals(activeAuto);
 }, [activeTab, activeAuto, selectedApplication, projectLabel, portfolio]);

 useEffect(() => {
   if (!selectedApplication || !projectLabel || !portfolio) return;
   requestAnimationFrame(() => loadAutomationTotals(activeAuto));
 }, [selectedApplication, projectLabel, portfolio, activeAuto]);

  // ---------------------------
  // BACKEND FETCHERS (same-origin)
  // ---------------------------

  const fetchDesignTotal = async ({ section, frmk, application }) => {
    // section: "design_new" | "design_existing"
    const params = new URLSearchParams({
      mode: "fetch",
      scope: "design",
      which: section,
      project: projectLabel,
      Domain: portfolio,
      AutomationFrmk: frmk,
      application: application || "",
    });
    const data = await GET(`${API_BASE}/api/masterdashboardfetchupdate?${params.toString()}`);
    // returns: { total: number }
    return Number.isFinite(+data?.total) ? +data.total : 0;
  };


  const fetchExecTotal = async ({ phase, frmk, application }) => {
    // phase: one of "DIT" | "SIT" | "UAT" | "Rollback" | "Roll Forward"
    const params = new URLSearchParams({
      mode: "fetch",
      scope: "execution",
      phase,                 // map handled server-side to SavingsCategory
      project: projectLabel,
      Domain: portfolio,
      AutomationFrmk: frmk,
      application: application || "",
    });
    const data = await GET(`${API_BASE}/api/masterdashboardfetchupdate?${params.toString()}`);
    return Number.isFinite(+data?.total) ? +data.total : 0;
  };

  const loadAutomationTotals = async (subKey) => {
    if (!projectLabel || !portfolio || !selectedApplication) return;

    // 1) New Automation
    const naTotal = await fetchDesignTotal({
      section: "design_new",
      frmk: subKey,
      application: selectedApplication,
    });

    // 2) Existing TCs Updated
    const exTotal = await fetchDesignTotal({
      section: "design_existing",
      frmk: subKey,
      application: selectedApplication,
    });

    // 3) Execution phases
    const execTotals = {};
    for (const ph of EXEC_PHASES) {
      execTotals[ph] = await fetchExecTotal({
        phase: ph,
        frmk: subKey,
        application: selectedApplication,
      });
    }

    // set into state (only 'total' fields)
    setAutoBySub((prev) => {
      const copy = { ...prev };
      const bundle = { ...copy[subKey] };

      bundle["New Automation"] = { ...bundle["New Automation"], total: naTotal };
      bundle["Existing TCs Updated"] = { ...bundle["Existing TCs Updated"], total: exTotal };

      const exec = { ...bundle["Execution (SIT + UAT)"] };
      EXEC_PHASES.forEach((ph) => {
        exec[ph] = { ...exec[ph], total: execTotals[ph] || 0 };
      });
      bundle["Execution (SIT + UAT)"] = exec;

      copy[subKey] = bundle;
      return copy;
    });
  };

  // SAVE (Design totals only, as per your note)
  const saveDesignTotals = async () => {
    const subKey = activeAuto;
    const NA = autoBySub[subKey]["New Automation"];
    const EX = autoBySub[subKey]["Existing TCs Updated"];

    if (!projectLabel || !portfolio || !selectedApplication) return;

    const body = {
      mode: "update",
      scope: "design",
      project: projectLabel,
      Domain: portfolio,
      AutomationFrmk: subKey,
      application: selectedApplication,
      // update only these two sections as requested
      updates: [
        {
          which: "design_new",
          func: num(NA.func),
          reg: num(NA.regression),
        },
        {
          which: "design_existing",
          func: num(EX.func),
          reg: num(EX.regression),
        },
      ],
    };

    const data = await POST(`${API_BASE}/api/masterdashboardfetchupdate`, body);
    if (data?.ok) {
      await loadAutomationTotals(subKey);
    }
  };

  //const execGrandTotal = (subKey) => {
  //  const exec = autoBySub[subKey]["Execution (SIT + UAT)"];
  //  return EXEC_PHASES.reduce((acc, p) => acc + num(exec[p].total), 0);
  //};



  // =========================
  // RENDERERS
  // =========================

  const ManualBlock = () => {
    return (
      <div className="mt-4">
        <div className="flex items-center justify-between">
          <h3 className="font-semibold text-gray-700">Manual (TDM) — Totals</h3>
        </div>

        <div className="grid grid-cols-2 gap-6 mt-3">
          <div className="p-3 border rounded-md">
            <div className="text-gray-600 font-medium mb-2">Designed</div>
            <div className="grid grid-cols-3 gap-2 items-end">
              <div>
                <label className="text-sm text-gray-600">Functional</label>
                <input
                  className="tab-input"
                  type="number"
                  value={manualDesigned.func}
                  onChange={(e) =>
                    setManualDesigned((p) => ({ ...p, func: e.target.value }))
                  }
                />
              </div>
              <div>
                <label className="text-sm text-gray-600">Regression</label>
                <input
                  className="tab-input"
                  type="number"
                  value={manualDesigned.regression}
                  onChange={(e) =>
                    setManualDesigned((p) => ({
                      ...p,
                      regression: e.target.value,
                    }))
                  }
                />
              </div>
              <div>
                <label className="text-sm text-gray-600">Total</label>
                <input
                  className="tab-input"
                  type="number"
                  value={manualDesigned.total}
                  readOnly
                />
                {sectionMismatch(manualDesigned) && (
                  <div className="text-xs text-red-700 mt-1">
                    (func + regression) ≠ total
                  </div>
                )}
              </div>
            </div>
          </div>

          <div className="p-3 border rounded-md">
            <div className="text-gray-600 font-medium mb-2">Executed</div>
            <div className="grid grid-cols-3 gap-2 items-end">
              <div>
                <label className="text-sm text-gray-600">Functional</label>
                <input
                  className="tab-input"
                  type="number"
                  value={manualExecuted.func}
                  onChange={(e) =>
                    setManualExecuted((p) => ({ ...p, func: e.target.value }))
                  }
                />
              </div>
              <div>
                <label className="text-sm text-gray-600">Regression</label>
                <input
                  className="tab-input"
                  type="number"
                  value={manualExecuted.regression}
                  onChange={(e) =>
                    setManualExecuted((p) => ({
                      ...p,
                      regression: e.target.value,
                    }))
                  }
                />
              </div>
              <div>
                <label className="text-sm text-gray-600">Total</label>
                <input
                  className="tab-input"
                  type="number"
                  value={manualExecuted.total}
                  readOnly
                />
                {sectionMismatch(manualExecuted) && (
                  <div className="text-xs text-red-700 mt-1">
                    (func + regression) ≠ total
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>

        <div className="mt-4">
          <button className="btn btn-secondary" onClick={saveDesignTotals}>
            Save (Design Totals Only)
          </button>
        </div>
      </div>
    );
  };

  const AutomationSimpleRow = ({ subKey, sectionName }) => {
    const val = autoBySub[subKey][sectionName];
    return (
      <div className="grid grid-cols-4 gap-4 items-end">
        <div>
          <label className="text-sm text-gray-600">Functional</label>
          <input
            className="tab-input"
            type="number"
            value={val.func}
            onChange={(e) => updateAuto(subKey, sectionName, "func", e.target.value)}
          />
        </div>
        <div>
          <label className="text-sm text-gray-600">Regression</label>
          <input
            className="tab-input"
            type="number"
            value={val.regression}
            onChange={(e) =>
              updateAuto(subKey, sectionName, "regression", e.target.value)
            }
          />
        </div>
        <div>
          <label className="text-sm text-gray-600">Total</label>
          <input className="tab-input" type="number" value={val.total} readOnly />
          {sectionMismatch(val) && (
            <div className="text-xs text-red-700 mt-1">
              (func + regression) ≠ total
            </div>
          )}
        </div>
      </div>
    );
  };

  const AutomationExecBlock = ({ subKey }) => {
    const ex = autoBySub[subKey]["Execution (SIT + UAT)"];
    return (
      <div className="grid grid-cols-5 gap-4 items-end">
        {EXEC_PHASES.map((p) => (
          <div key={p}>
            <label className="text-sm text-gray-600">{p}</label>
            <input
              className="tab-input"
              type="number"
              value={ex[p].total}
              onChange={(e) => updateExec(subKey, p, e.target.value)}
            />
          </div>
        ))}
      </div>
    );
  };

  const AutomationBlock = () => {
    return (
      <div className="mt-4">
        {/* sub-tabs */}
        <div className="mb-3 flex flex-wrap gap-2">
          {AUTO_SUB_TABS.map((k) => (
            <button
              key={k}
              className={`btn ${activeAuto === k ? "btn-primary" : "btn-secondary"}`}
              onClick={() => setActiveAuto(k)}
              style={{ opacity: activeAuto === k ? 1 : 0.65 }}
            >
              {k}
            </button>
          ))}
        </div>

        <div className="p-3 border rounded-md space-y-4">
          <AutomationSimpleRow subKey={activeAuto} sectionName="New Automation" />
          <AutomationSimpleRow subKey={activeAuto} sectionName="Existing TCs Updated" />

          <div>
            <div className="text-gray-600 font-medium mb-2">Execution (SIT + UAT)</div>
            <AutomationExecBlock subKey={activeAuto} />
          </div>
        </div>

        <div className="mt-4">
          <button className="btn btn-secondary" onClick={saveDesignTotals}>
            Save (Design Totals Only)
          </button>
        </div>
      </div>
    );
  };

  return (
    <div className="p-4">
      {/* Tabs */}
      <div className="mb-4 flex gap-2">
        <button
          className={`btn ${activeTab === "Manual" ? "btn-primary" : "btn-secondary"}`}
          onClick={() => setActiveTab("Manual")}
        >
          Manual (TDM)
        </button>
        <button
          className={`btn ${activeTab === "Automation" ? "btn-primary" : "btn-secondary"}`}
          onClick={() => setActiveTab("Automation")}
        >
          Automation
        </button>

        {/* Application selector (drives the Master Dashboard API) */}
        <div style={{ marginLeft: "auto" }}>
          <label className="text-sm text-gray-600 mr-2">Select an Application</label>
          <select
            className="select-red"
            style={{ width: 200, padding: "4px 6px" }}
            value={selectedApplication}
            onChange={(e) => setSelectedApplication(e.target.value)}
          >
            <option value="">{`<Select an Application>`}</option>
            {(apiAppOptions.length > 0 ? apiAppOptions : applicationOptions).map((o) => (
              <option key={o} value={o}>
                {o}
              </option>
            ))}
          </select>
        </div>
      </div>

      {activeTab === "Manual" ? <ManualBlock /> : <AutomationBlock />}
    </div>
  );
}
